def get_translation(key: str, lang: str) -> str:
    """
    Returns localized text for a domain key and language code.
    Falls back to English if key is missing in target language.
    """
    if lang in TRANSLATIONS and key in TRANSLATIONS[lang]:
        return TRANSLATIONS[lang][key]
    if "en" in TRANSLATIONS and key in TRANSLATIONS["en"]:
        return TRANSLATIONS["en"][key]
    return ""
